import { ChangeDetectionStrategy, Component, Input, signal } from "@angular/core";
import { CommonModule } from "@angular/common";
import { Message } from "../../models/types";
import { IconComponent } from "../icon/icon.component";
import { ToastService } from "../../services/toast.service";

/**
 * AI rated message — long text with thumbs feedback, copy, regenerate.
 * Mirrors React `<AIRatedMessage>`.
 */
@Component({
  selector: "app-ai-rated-message",
  standalone: true,
  imports: [CommonModule, IconComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="rounded-2xl bg-white border border-gray-200 max-w-lg w-full overflow-hidden shadow-sm">
      <div class="px-4 py-3 text-[14px] leading-relaxed text-gray-900 whitespace-pre-wrap">
        {{ msg.text }}
      </div>
      <div *ngIf="msg.sources?.length" class="px-4 pb-3 flex flex-wrap gap-1.5">
        <span *ngFor="let s of msg.sources"
              class="text-[11px] px-2 py-0.5 rounded-full bg-blue-50 text-blue-700 border border-blue-100">
          {{ s }}
        </span>
      </div>
      <div class="border-t border-gray-100 px-3 py-2 flex items-center gap-1 bg-gray-50/30">
        <button
          (click)="setFeedback('up')"
          [class]="'h-7 w-7 rounded-full flex items-center justify-center transition ' +
            (feedback() === 'up' ? 'bg-blue-100 text-blue-700' : 'hover:bg-gray-100 text-gray-600')"
          title="Good response"
        >
          <app-icon name="thumbs-up" [size]="14"></app-icon>
        </button>
        <button
          (click)="setFeedback('down')"
          [class]="'h-7 w-7 rounded-full flex items-center justify-center transition ' +
            (feedback() === 'down' ? 'bg-rose-100 text-rose-700' : 'hover:bg-gray-100 text-gray-600')"
          title="Needs improvement"
        >
          <app-icon name="thumbs-down" [size]="14"></app-icon>
        </button>
        <div class="w-px h-4 bg-gray-200 mx-1"></div>
        <button
          (click)="handleCopy()"
          class="h-7 px-2 rounded-full hover:bg-gray-100 text-gray-600 flex items-center gap-1 text-[11px]"
          title="Copy"
        >
          <app-icon name="copy" [size]="12"></app-icon>
          {{ copied() ? "Copied" : "Copy" }}
        </button>
        <button
          class="h-7 px-2 rounded-full hover:bg-gray-100 text-gray-600 flex items-center gap-1 text-[11px]"
          title="Regenerate"
        >
          <app-icon name="refresh-cw" [size]="12"></app-icon>
          Regenerate
        </button>
        <span class="ml-auto text-[10px] text-gray-500">Generated by Airlift Intelligence</span>
      </div>
    </div>
  `,
})
export class AIRatedMessageComponent {
  @Input() msg!: Message;
  feedback = signal<"up" | "down" | null>(null);
  copied = signal(false);

  constructor(private toast: ToastService) {}

  setFeedback(v: "up" | "down"): void {
    this.feedback.set(this.feedback() === v ? null : v);
  }

  handleCopy(): void {
    const text = this.msg.text || "";
    if (navigator.clipboard) {
      navigator.clipboard.writeText(text).catch(() => {});
    }
    this.copied.set(true);
    setTimeout(() => this.copied.set(false), 1500);
  }
}
